#!/usr/bin/env python3
"""Build the static Claw support site without third-party scripts or analytics."""
import argparse
from html import escape
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]
SOURCE = "https://github.com/floaterrrrrr/Claw-Emulator"
ORIGIN = "https://claw-emulator.sunsetpine6.chatgpt.site"

CSS = '''
:root{color-scheme:dark;--bg:#171b1d;--panel:#202527;--line:#363d40;--ink:#f7f7f4;--muted:#abb1b2;--accent:#f38d4a;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-size:17px;line-height:1.65}a{color:var(--accent);text-underline-offset:4px}a:hover{color:#ffc39a}a:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}header,main,footer{max-width:1120px;margin:auto;padding-left:28px;padding-right:28px}header{display:flex;justify-content:space-between;align-items:center;gap:24px;padding-top:26px;padding-bottom:26px;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--ink);font-size:25px;font-weight:700}.brand img{width:48px;height:48px;border-radius:14px}nav{display:flex;gap:26px;flex-wrap:wrap}nav a{font-size:15px;color:var(--muted);text-decoration:none}nav a[aria-current=page]{color:var(--accent)}main{padding-top:64px;padding-bottom:80px}h1,h2,h3{line-height:1.15;letter-spacing:-.035em}h1{font-size:clamp(40px,7vw,70px);font-weight:700;max-width:860px;margin:14px 0 22px}h2{font-size:29px;margin-top:38px}h3{font-size:21px}.eyebrow{color:var(--accent);font-size:13px;letter-spacing:.12em;text-transform:uppercase;font-weight:700}.lead{font-size:21px;color:var(--muted);max-width:690px}.hero{padding-bottom:44px;max-width:840px}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}.button{border-radius:999px;padding:13px 25px;border:1px solid var(--line);text-decoration:none;color:var(--ink);font-weight:600;display:inline-flex;align-items:center;justify-content:center;min-height:48px}.button.primary{background:var(--accent);border-color:var(--accent);color:#171b1d}.button:hover{border-color:var(--accent)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:var(--panel);border:1px solid var(--line);border-radius:28px;padding:28px}.card p{color:var(--muted)}.card h2{font-size:24px;margin:0 0 14px}.card a{display:inline-block;padding:8px 0}.systems{display:flex;flex-wrap:wrap;gap:10px;margin:28px 0}.systems span{padding:7px 16px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:14px}.prose{max-width:780px}.prose p,.prose li{color:#c6cbcb}.prose h2{padding-top:12px}details{border:1px solid var(--line);border-radius:22px;background:var(--panel);margin:14px 0;padding:0 24px}summary{padding:21px 0;cursor:pointer;font-weight:600}details p,details ul{margin-top:0;padding-bottom:12px;color:#c6cbcb}.note{border-left:3px solid var(--accent);padding:2px 0 2px 21px;color:var(--muted);margin:30px 0}code{font-size:.87em;background:#2b3134;border-radius:6px;padding:2px 6px;overflow-wrap:anywhere}footer{border-top:1px solid var(--line);padding-top:26px;padding-bottom:36px;color:var(--muted);font-size:13px;display:flex;justify-content:space-between;gap:25px;flex-wrap:wrap}footer a{color:var(--muted)}.skip{position:absolute;top:-80px;left:20px}.skip:focus{top:10px;background:var(--panel);padding:10px}.small{font-size:14px;color:var(--muted)}@media(max-width:720px){header{align-items:flex-start;flex-direction:column;gap:18px}nav{gap:22px}.grid{grid-template-columns:1fr}main{padding-top:38px;padding-bottom:50px}header,main,footer{padding-left:22px;padding-right:22px}.lead{font-size:19px}.card{padding:24px}h2{font-size:26px}}
'''

def page(title, route, body):
    nav = ''.join(f'<a href="{path}"'+(' aria-current="page"' if route == path else '')+f'>{name}</a>' for name,path in [('Support','/support/'),('Privacy','/privacy/'),('Source','/source/')])
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Claw emulator support, privacy information and open-source build materials."><title>{escape(title)} · Claw</title><link rel="icon" href="/assets/claw.png"><link rel="stylesheet" href="/style.css"><link rel="canonical" href="{ORIGIN}{route}"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/"><img src="/assets/claw.png" alt="" width="48" height="48">Claw</a><nav aria-label="Main navigation">{nav}</nav></header><main id="main">{body}</main><footer><span>Claw · Your games. Your library.</span><span><a href="mailto:feedback@salamlabs.io">feedback@salamlabs.io</a> · <a href="/privacy/">Privacy</a> · <a href="/source/">Open source</a></span></footer></body></html>'''

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output',type=Path,required=True)
    out=parser.parse_args().output.resolve()
    out.mkdir(parents=True,exist_ok=True)
    (out/'assets').mkdir(exist_ok=True)
    shutil.copyfile(ROOT/'App/Assets.xcassets/AppIconOrange.appiconset/Icon-1024.png',out/'assets/claw.png')
    (out/'style.css').write_text(CSS,encoding='utf-8')
    home='''<section class="hero"><div class="eyebrow">The Claw emulator</div><h1>A place for your<br>next adventure.</h1><p class="lead">Your compatible games, together on iPhone. Find help, understand your privacy, and explore the source behind Claw.</p><div class="systems" aria-label="Supported systems"><span>3DS</span><span>DS</span><span>GBA</span><span>GB</span><span>GBC</span><span>NES</span></div><div class="buttons"><a class="button primary" href="/support/">Get started</a><a class="button" href="/source/">Explore the source ↗</a></div></section><div class="grid"><section class="card"><h2>Make yourself at home.</h2><p>Import from Files, set up your controls, and keep your progress close.</p><a href="/support/">Help &amp; support →</a></section><section class="card"><h2>Your library stays yours.</h2><p>No Claw account, ads, analytics SDKs, or developer-operated game uploads.</p><a href="/privacy/">Read the privacy policy →</a></section><section class="card"><h2>Open-source foundations.</h2><p>Find repository details, dependency notices, and build information.</p><a href="/source/">Source &amp; licenses →</a></section></div><p class="note">Claw does not include games or console files. Import only content you have the right to use. Compatibility and performance vary by game and device.</p>'''
    support='''<section class="hero"><div class="eyebrow">Help &amp; support</div><h1>Back to your game.</h1><p class="lead">A little help with your library, controls, and progress.</p><div class="buttons"><a class="button primary" href="mailto:feedback@salamlabs.io?subject=Claw%20support">Email support ↗</a></div></section><div class="prose"><details open><summary>How do I import a game?</summary><p>Open <strong>Library → Import</strong>, then choose a compatible file in Files. Import only games you have the right to use. Claw includes no games or console files.</p><p>3DS: decrypted <code>.cia</code>, <code>.cci</code>, <code>.3ds</code>, <code>.cxi</code>, <code>.app</code>, and <code>.3dsx</code> homebrew. DS: <code>.nds</code>. GBA: <code>.gba</code>. GB: <code>.gb</code>. GBC: <code>.gbc</code>. NES: <code>.nes</code>.</p></details><details><summary>Can I import ZIP or 7z archives?</summary><p>An archive containing one supported game can be imported. A cloud file provider may need to finish downloading first. If unpacking fails, extract the archive in Files or another archive app and import the game file inside. Unsupported archive methods and encrypted game files cannot be imported.</p></details><details><summary>How do I keep or export my saves?</summary><p>Use the game's own save menu for regular progress. Save states are available from the in-game menu. You can export saves and system data through the iOS share sheet. Review the archive before sharing: it can include imported console keys.</p></details><details><summary>How do I change controls or skins?</summary><p>Use Skins for compatible portrait and landscape layouts. The in-game menu includes control settings. Available controls and layouts depend on the selected system and skin.</p></details><details><summary>Why is a game slow or not starting?</summary><p>Compatibility varies by game and iPhone. Check that the file is supported and decrypted where required, and that there is enough free storage. Some 3DS games require console data that you supply separately. Try the default graphics settings and normal speed before reporting a problem.</p></details><details><summary>How do I report a problem?</summary><p>Email <a href="mailto:feedback@salamlabs.io">feedback@salamlabs.io</a> with your iPhone model, iOS version, Claw version/build, game system, and steps to reproduce the issue. Screenshots can help if you have permission to share them. Do not send commercial game files, console keys, or private save data.</p></details><h2>Privacy and source</h2><p>Read our <a href="/privacy/">privacy policy</a> or explore <a href="/source/">Claw's source and dependency notices</a>. Claw is an independent project and is not affiliated with or endorsed by console makers or game publishers.</p></div>'''
    policy=(ROOT/'App/Legal/PrivacyPolicy.txt').read_text(encoding='utf-8').strip().split('\n\n')
    paragraphs=[]
    for chunk in policy[2:]:
        parts=chunk.split('\n',1)
        if len(parts)==2 and len(parts[0])<60:
            paragraphs.append('<h2>'+escape(parts[0])+'</h2><p>'+escape(parts[1]).replace('\n','<br>')+'</p>')
        else: paragraphs.append('<p>'+escape(chunk).replace('\n','<br>')+'</p>')
    privacy='<div class="prose"><div class="eyebrow">Your privacy</div><h1>Claw Privacy Policy</h1><p class="small">'+escape(policy[1])+'</p>'+''.join(paragraphs)+'</div>'
    source=f'''<section class="hero"><div class="eyebrow">Source &amp; credits</div><h1>The source behind Claw.</h1><p class="lead">Claw's release repository contains the app source, dependency pins, build recipes, and license notices.</p><p class="note">The new repository is private during release preparation. Access on GitHub is limited to authorized accounts until the owner makes it public.</p><div class="buttons"><a class="button primary" href="{SOURCE}">Claw-Emulator on GitHub ↗</a></div></section><div class="prose"><h2>Releases you can inspect</h2><p>Each published source snapshot records its development commit in <code>SOURCE_SNAPSHOT.json</code>. Source packages include checksum-pinned upstream archives and local build scripts. Consult the release notes for the matching Claw build.</p><h2>Credits where they belong</h2><p>Claw builds on Cytrus, Azahar, Citra, and the open-source projects used for its other supported systems. MoltenVK provides Vulkan-to-Metal translation. FFmpeg is built from pinned source in Xcode Cloud.</p><p>Claw's overall source license is GNU GPL v3. Individual dependencies retain their own licenses and notices. Full notices are available in <strong>Settings → Legal &amp; licenses</strong> inside Claw and in the source repository.</p><div class="buttons"><a class="button" href="{SOURCE}/blob/main/App/Legal/ThirdPartyNotices.txt">Read notices ↗</a><a class="button" href="{SOURCE}/blob/main/Distribution/source-readiness.md">Build &amp; provenance notes ↗</a></div><h2>Build it yourself</h2><p>The repository includes instructions for macOS and Xcode, pinned dependencies, and scripts to rebuild FFmpeg and the emulator cores. Your own signing identity is required to install signed builds. Source packages contain no commercial games, console keys, or signing credentials.</p><p>For source-access questions, email <a href="mailto:feedback@salamlabs.io?subject=Claw%20source">feedback@salamlabs.io</a>.</p></div>'''
    for route,title,body in [('/', 'Your game library',home),('/support/','Support',support),('/privacy/','Privacy policy',privacy),('/source/','Source & licenses',source)]:
        target=out/route.strip('/')/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(page(title,route,body),encoding='utf-8')
    (out/'robots.txt').write_text('User-agent: *\nAllow: /\n',encoding='utf-8')
    print(f'Built four static pages at {out}')

if __name__=='__main__': main()
